func traceSVGPath(cr *cairo.Context, d string) {
	var cmd byte
	var x, y float64
	i := 0
	next := func() float64 {
		for i < len(d) && (d[i] == ' ' || d[i] == ',') {
			i++
		}
		start := i
		for i < len(d) && (d[i] == '-' || d[i] == '.' || d[i] == 'e' || (d[i] >= '0' && d[i] <= '9')) {
			i++
		}
		v, _ := strconv.ParseFloat(d[start:i], 64)
		return v
	}
	for i < len(d) {
		switch c := d[i]; {
		case c == ' ' || c == ',':
			i++
			continue
		case c == 'Z':
			cr.ClosePath()
			i++
			continue
		case c >= 'A' && c <= 'Z':
			cmd = c
			i++
		}
		switch cmd {
		case 'M':
			x, y = next(), next()
			cr.MoveTo(x, y)
			cmd = 'L'
		case 'L':
			x, y = next(), next()
			cr.LineTo(x, y)
		case 'H':
			x = next()
			cr.LineTo(x, y)
		case 'V':
			y = next()
			cr.LineTo(x, y)
		case 'C':
			x1, y1, x2, y2 := next(), next(), next(), next()
			x, y = next(), next()
			cr.CurveTo(x1, y1, x2, y2, x, y)
		default:
			return
		}
	}
}
